        PackagePart mockDocumentPart = Mockito.mock(PackagePart.class);
        Mockito.when(mockDocumentPart.addRelationship(
                any(PackagePartName.class), 
                any(TargetMode.class), 
                anyString()))
                .thenReturn(Mockito.mock(org.apache.poi.openxml4j.opc.PackageRelationship.class));

        org.apache.poi.xwpf.usermodel.NiceXWPFDocument niceDocument = 
                new org.apache.poi.xwpf.usermodel.NiceXWPFDocument(mockPackage);

