        java.lang.reflect.Field packagePartField = org.apache.poi.xwpf.usermodel.NiceXWPFDocument.class
                .getDeclaredField("packagePart");
        packagePartField.setAccessible(true);
        packagePartField.set(niceDocument, mockDocumentPart);

        niceDocument.addEmbeddData(testData, contentType, partPath);
    }
}

