 * close the document
 *
 * @throws IOException
 */
@Override
public void close() throws IOException {
    this.doc.close();
}

/**
 * reload the template
 *
 * @param doc
 * 		load new template document
 */
public void reload(NiceXWPFDocument doc) {
    PoitlIOUtils.closeLoggerQuietly(this.doc);
    this.doc = doc;
    this.eleTemplates = this.resolver.resolveDocument(doc);
}

/**
