package com.deepoove.poi.xwpf;

import org.apache.poi.xwpf.usermodel.IBody;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.xmlbeans.XmlCursor;
import org.apache.xmlbeans.XmlObject;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.mock;

public class BodyContainerinsertNewParagraph_IBodyinsertNewParagraphFikaTest {

    @Test
    void testInsertNewParagraph() throws Exception {
        XmlCursor cursor = null;
        try {
            XmlObject xmlObject = XmlObject.Factory.newInstance();
            cursor = xmlObject.newCursor();

            IBody mockBody = mock(IBody.class);
            XWPFParagraph mockParagraph = mock(XWPFParagraph.class);

            Mockito.when(mockBody.insertNewParagraph(cursor)).thenReturn(mockParagraph);

            IBody bodyUnderTest = new IBody() {
                @Override
                public XWPFParagraph insertNewParagraph(XmlCursor insertPositionCursor) {
                    return mockBody.insertNewParagraph(insertPositionCursor);
                }

                @Override
                public IBody getTarget() {
                    return mockBody;
                }
            };

            bodyUnderTest.insertNewParagraph(cursor);
        } finally {
            if (cursor != null) {
                cursor.dispose();
            }
        }
    }
}

