    public void testMerge() throws Exception {
        // Create real CTBody object
        CTBody body = CTBody.Factory.newInstance();

        // Create mock NiceXWPFDocument for source
        NiceXWPFDocument source = Mockito.mock(NiceXWPFDocument.class);
        NiceXWPFDocument sourceDocument = Mockito.mock(NiceXWPFDocument.class);
        Mockito.when(source.getDocument()).thenReturn(sourceDocument);
        Mockito.when(sourceDocument.getBody()).thenReturn(body);

        // Create mock iterator
        Iterator<NiceXWPFDocument> mergeIterator = Collections.<NiceXWPFDocument>emptyList().iterator();

        // Create mock run and paragraph
        XWPFRun run = Mockito.mock(XWPFRun.class);
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        Mockito.when(run.getParent()).thenReturn(paragraph);

        // Create real CTP object
        CTP mergedContainer = CTP.Factory.newInstance();
        Mockito.when(paragraph.getCTP()).thenReturn(mergedContainer);

        // Mock the generate method to return a NiceXWPFDocument
        NiceXWPFDocument generatedDoc = Mockito.mock(NiceXWPFDocument.class);
        Mockito.when(source.generate(Mockito.anyBoolean())).thenReturn(generatedDoc);

        // Create the class under test
        Object testInstance = new Object() {
            public NiceXWPFDocument merge(NiceXWPFDocument source, Iterator<NiceXWPFDocument> mergeIterator, XWPFRun run) throws Exception {
