        workbook.createSheet().createRow(0).createCell(0).setCellValue("Test");

        // Create a mock XWPFChart that returns our workbook
        XWPFChart chart = Mockito.mock(XWPFChart.class);
        when(chart.getWorkbook()).thenReturn(workbook);

        // Create a NiceXWPFDocument instance
