        // Create a minimal package part for the chart
        org.apache.poi.openxml4j.opc.PackagePart packagePart = 
            org.apache.poi.openxml4j.opc.OPCPackage.create(
                new ByteArrayInputStream(new byte[0])
            ).createPart(
                org.apache.poi.openxml4j.opc.PackagingURIHelper.createPartName("/word/charts/chart1.xml"),
                "application/vnd.openxmlformats-officedocument.drawingml.chart+xml"
            );

        when(chart.getPackagePart()).thenReturn(packagePart);

        // Execute the method - this will trigger xwpfChart.setWorkbook()
        document.addChartData(chart);

        // Clean up
        workbook.close();
        packagePart.getPackage().close();
    }
}

