        when(xwpfChart.getWorkbook().getSheetAt(0)).thenReturn(mock(org.apache.poi.ss.usermodel.Sheet.class));

        SingleSeriesChartTemplateRenderPolicy policy = new SingleSeriesChartTemplateRenderPolicy();
        policy.doRender(chartTemplate, chartSingleSeriesRenderData, xwpfTemplate);
    }
}

