                return new XSSFWorkbook(new ByteArrayInputStream(out.toByteArray()));
            } finally {
                if (closed)
                    closeQuietly(src);

                closeQuietly(out);
            }
        }

        private static void closeQuietly(AutoCloseable closeable) {
            if (closeable != null) {
                try {
                    closeable.close();
                } catch (Exception e) {
                    // Ignore
                }
            }
        }
    }

    // ByteArrayInputStream is needed for the method
    private static class ByteArrayInputStream extends java.io.InputStream {
        private byte[] buf;
