        private int mark = 0;
        private int count;

        public ByteArrayInputStream(byte[] buf) {
            this.buf = buf;
            this.pos = 0;
            this.count = buf.length;
        }

        @Override
        public int read() {
            return (pos < count) ? (buf[pos++] & 0xff) : -1;
        }
    }
}

