import org.openxmlformats.schemas.drawingml.x2006.chart.CTPlotArea;
import java.util.Arrays;
import java.util.List;

@ExtendWith(MockitoExtension.class)
public class SingleSeriesChartTemplateRenderPolicydoRender_SeriesreplaceDataFikaTest {

    @Mock
    private ChartTemplate eleTemplate;

    @Mock
    private ChartSingleSeriesRenderData data;

    @Mock
    private SeriesRenderData seriesDatas;

    @Mock
    private com.deepoove.poi.XWPFChart chart;

    @Mock
    private XDDFScatterChartData pie;

    @Mock
    private XDDFChartData.Series currentSeries;

    @Mock
    private XDDFDataSource<?> categoriesData;

    @Mock
    private XDDFNumericalDataSource<? extends Number> valuesData;

    @Mock
    private com.deepoove.poi.XWPFTemplate template;

    @Mock
    private XSSFWorkbook workbook;

    @Mock
    private XSSFSheet sheet;

    @Mock
    private CTChart ctChart;

    @Mock
    private CTPlotArea ctPlotArea;

    @Test
    public void testDoRender() throws Exception {
        SingleSeriesChartTemplateRenderPolicy policy = new SingleSeriesChartTemplateRenderPolicy();

        java.lang.reflect.Method method = SingleSeriesChartTemplateRenderPolicy.class
            .getDeclaredMethod("doRender", ChartTemplate.class, ChartSingleSeriesRenderData.class, 
                             com.deepoove.poi.XWPFTemplate.class);
        method.setAccessible(true);

        when(eleTemplate.getChart()).thenReturn(chart);
        when(com.deepoove.poi.policy.reference.ChartUtils.getChartSeries(chart))
            .thenReturn(Arrays.asList(pie));
        when(data.getSeriesData()).thenReturn(seriesDatas);
        when(data.getCategories()).thenReturn(Arrays.asList("Cat1", "Cat2"));
        when(seriesDatas.getValues()).thenReturn(Arrays.asList(10.0, 20.0));
        when(seriesDatas.getName()).thenReturn("Series1");
        when(data.getChartTitle()).thenReturn("Chart Title");
        when(data.getxAxisTitle()).thenReturn("X Axis");
        when(data.getyAxisTitle()).thenReturn("Y Axis");
        when(pie.getSeries(0)).thenReturn(currentSeries);
        when(chart.getWorkbook()).thenReturn(workbook);
        when(workbook.getSheetAt(0)).thenReturn(sheet);
        when(chart.getCTChart()).thenReturn(ctChart);
        when(ctChart.getPlotArea()).thenReturn(ctPlotArea);

        method.invoke(policy, eleTemplate, data, template);
    }
}

