            paragraphs.add(p);
            bodyElements.add(p);
        }
        if (o instanceof CTSdtBlock) {
            XWPFSDT c = new XWPFSDT(((CTSdtBlock) (o)), this);
            bodyElements.add(c);
        }
        // if (o instanceof CTSdtRun) {
        // XWPFSDT c = new XWPFSDT((CTSdtRun) o, this);
        // bodyElements.add(c);
