package com.deepoove.poi.util;

import org.junit.jupiter.api.Test;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTBorder;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STBorder;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTColor;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STColor;
import org.apache.xmlbeans.XmlObject;
import org.apache.xmlbeans.XmlString;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class StyleUtilsretriveBorderStyle_CTBorderxgetColorFikaTest {

    @Test
    public void testRetriveBorderStyle() {
        // Create a real CTBorder instance
        CTBorder border = CTBorder.Factory.newInstance();

        // Create a mock CTColor to return from xgetColor()
        CTColor mockColor = mock(CTColor.class);
        when(mockColor.getStringValue()).thenReturn("#000000");

        // Set up the border to have color set
        border.setColor(STColor.Factory.newValue("#000000"));

        // Create a mock for the xgetColor() method return
        // We need to use reflection to set the xgetColor return value
        try {
            // Get the XmlCursor to modify the underlying XML
            XmlObject colorObj = CTColor.Factory.newInstance();
            colorObj.set(mockColor);

            // Use reflection to set the color field
            java.lang.reflect.Field colorField = CTBorder.class.getDeclaredField("color");
            colorField.setAccessible(true);
            colorField.set(border, colorObj);

            // Set the color field to be present
            java.lang.reflect.Field colorSetField = CTBorder.class.getDeclaredField("color$flags");
            colorSetField.setAccessible(true);
            short flags = (short) colorSetField.get(border);
            flags |= 0x01; // Set the color flag
            colorSetField.set(border, flags);

        } catch (Exception e) {
            // If reflection fails, create a border with all required fields
            border = CTBorder.Factory.newInstance();
            border.setColor(STColor.Factory.newValue("#000000"));
            border.setSz(4);
            border.setVal(STBorder.SINGLE);
        }

        // Execute the method - this will invoke border.xgetColor()
        StyleUtils.retriveBorderStyle(border);
    }
}

