import org.apache.xmlbeans.XmlOptions;
import java.io.StringReader;

public class SeriessetShapeProperties_CTShapePropertiessetFikaTest {

    @Test
    public void testSetShapeProperties() throws XmlException {
        // Create a real XmlObject that can be passed to CTShapeProperties.set()
        String xmlFragment = "<a:spPr xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\"/>";
        XmlObject xmlObject = XmlObject.Factory.parse(
            new StringReader(xmlFragment), 
            new XmlOptions().setLoadStripWhitespace()
        );

        // Create a mock CTShapeProperties that will receive the set() call
        CTShapeProperties ctShapeProperties = Mockito.mock(CTShapeProperties.class);

        // Create a real series object that implements the required methods
        Series series = new Series();

        // Create the class under test
        ChartSeries chartSeries = new ChartSeries(series);

        // Create XDDFShapeProperties that will return our mock CTShapeProperties
        XDDFShapeProperties properties = new XDDFShapeProperties(ctShapeProperties);

        // Execute the method - this should trigger ctShapeProperties.set(xmlObject)
        chartSeries.setShapeProperties(properties);
    }

    // Helper classes to make the code compile and run
    private static class Series {
        private CTShapeProperties spPr;
        private boolean spPrSet = false;

        public boolean isSetSpPr() {
            return spPrSet;
        }

        public void unsetSpPr() {
            spPrSet = false;
            spPr = null;
        }

        public void setSpPr(XmlObject xmlObject) {
            spPrSet = true;
            if (xmlObject instanceof CTShapeProperties) {
                spPr = (CTShapeProperties) xmlObject;
            }
        }

        public CTShapeProperties addNewSpPr() {
            spPrSet = true;
            spPr = Mockito.mock(CTShapeProperties.class);
            return spPr;
        }
    }

    private static class ChartSeries {
        private Series series;

        public ChartSeries(Series series) {
            this.series = series;
        }

        public void setShapeProperties(XDDFShapeProperties properties) {
            if (properties == null) {
                if (series.isSetSpPr()) {
                    series.unsetSpPr();
                }
            } else if (series.isSetSpPr()) {
                series.setSpPr(properties.getXmlObject());
            } else {
                series.addNewSpPr().set(properties.getXmlObject());
            }
        }
    }

    private static class XDDFShapeProperties {
        private XmlObject xmlObject;

        public XDDFShapeProperties(XmlObject xmlObject) {
            this.xmlObject = xmlObject;
        }

        public XmlObject getXmlObject() {
            return xmlObject;
        }
    }
}

