public NiceXWPFDocument(InputStream in, boolean adjustDoc) throws IOException {
    super(in);
    this.adjustDoc = adjustDoc;
    idenifierManagerWrapper = new IdenifierManagerWrapper(this);
    niceDocumentRead();
}

