    while (cursor.toNextSelection()) {
        XmlObject o = cursor.getObject();
        if (o instanceof CTP) {
            XWPFParagraph p = new XWPFParagraph(((CTP) (o)), this);
            paragraphs.add(p);
            bodyElements.add(p);
        }
