package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;

import static org.mockito.Mockito.*;

public class StyleUtilsstyleTable_CTTblWidthsetWFikaTest {

    @Test
    public void testStyleTableInvokesCTTblWidthSetW() {
        // Create a real TableStyle with indentation to trigger the target path
        TableStyle tableStyle = new TableStyle();
        tableStyle.setIndentation(2.5); // Any positive value works

        // Create a mock XWPFTable that returns necessary CTTbl structure
        XWPFTable mockTable = mock(XWPFTable.class);

        // Mock the CTTbl structure to ensure the target method is called
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTbl mockCtTbl = 
            mock(org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTbl.class);
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblPr mockTblPr = 
            mock(org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblPr.class);
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblWidth mockTblWidth = 
            mock(org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblWidth.class);

        // Setup the chain of calls
        when(mockTable.getCTTbl()).thenReturn(mockCtTbl);
        when(mockCtTbl.getTblPr()).thenReturn(null); // Force addNewTblPr()
        when(mockCtTbl.addNewTblPr()).thenReturn(mockTblPr);
        when(mockTblPr.isSetTblInd()).thenReturn(false); // Force addNewTblInd()
        when(mockTblPr.addNewTblInd()).thenReturn(mockTblWidth);

        // Execute the method under test
        StyleUtils.styleTable(mockTable, tableStyle);

        // The test passes if execution reaches tw.setW(...) without throwing exceptions
