package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayOutputStream;
import java.math.BigInteger;

class TableToolswidthTable_CTTblPraddNewTblWFikaTest {

    @Test
    void testWidthTable() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFTable table = document.createTable();

        float[] colWidths = new float[]{0.5f, 0.5f};

        TableWidth.widthTable(table, colWidths);

        document.close();
    }

    private static class TableWidth {
        @Deprecated
        public static void widthTable(XWPFTable table, float[] colWidths) {
            float widthCM = 0;
            for (float w : colWidths) {
                widthCM += w;
            }
            int width = UnitUtils.cm2Twips(widthCM);
            CTTblPr tblPr = getTblPr(table);
            CTTblWidth tblW = (tblPr.isSetTblW()) ? tblPr.getTblW() : tblPr.addNewTblW();
            tblW.setType(0 == width ? STTblWidth.AUTO : STTblWidth.DXA);
            tblW.setW(BigInteger.valueOf(width));
            if (0 != width) {
                CTTblGrid tblGrid = getTblGrid(table);
                for (float w : colWidths) {
                    CTTblGridCol addNewGridCol = tblGrid.addNewGridCol();
                    addNewGridCol.setW(BigInteger.valueOf(UnitUtils.cm2Twips(w)));
                }
            }
        }

        private static CTTblPr getTblPr(XWPFTable table) {
            return table.getCTTbl().getTblPr();
        }

        private static CTTblGrid getTblGrid(XWPFTable table) {
            return table.getCTTbl().getTblGrid();
        }
    }

    private static class UnitUtils {
        public static int cm2Twips(float cm) {
            return (int)(cm * 567);
        }
    }

    private static class CTTblPr {
        private CTTblWidth tblW;
        private boolean tblWSet = false;

        public boolean isSetTblW() {
            return tblWSet;
        }

        public CTTblWidth getTblW() {
            return tblW;
        }

        public CTTblWidth addNewTblW() {
            tblW = new CTTblWidth();
            tblWSet = true;
            return tblW;
        }
    }

    private static class CTTblWidth {
        private STTblWidth type;
        private BigInteger w;

        public void setType(STTblWidth type) {
            this.type = type;
        }

        public void setW(BigInteger w) {
            this.w = w;
        }
    }

    private static class CTTblGrid {
        public CTTblGridCol addNewGridCol() {
            return new CTTblGridCol();
        }
    }

    private static class CTTblGridCol {
        public void setW(BigInteger w) {
        }
    }

    private enum STTblWidth {
        AUTO, DXA
    }
}

