        // Create mock source paragraph
        XWPFParagraph sourceParagraph = Mockito.mock(XWPFParagraph.class);
        Mockito.when(sourceParagraph.getDocument()).thenReturn(document);
        Mockito.when(sourceParagraph.getNumID()).thenReturn(BigInteger.valueOf(1));

        // Create mock target paragraph
        XWPFParagraph targetParagraph = Mockito.mock(XWPFParagraph.class);

        // Create real numbering wrapper
        com.deepoove.poi.xwpf.XWPFNumberingWrapper wrapper = 
            new com.deepoove.poi.xwpf.XWPFNumberingWrapper(numbering);

        // Create real CTAbstractNum
        CTAbstractNum ctAbstractNum = CTAbstractNum.Factory.newInstance();

        // Create real XWPFNum with mocked CTNum
        XWPFNum num = Mockito.mock(XWPFNum.class);
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTNum ctNum = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTNum.Factory.newInstance();
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTDecimalNumber abstractNumId = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTDecimalNumber.Factory.newInstance();
        abstractNumId.setVal(BigInteger.valueOf(1));
        ctNum.setAbstractNumId(abstractNumId);
        Mockito.when(num.getCTNum()).thenReturn(ctNum);

        // Mock numbering to return the num
        Mockito.when(numbering.getNum(Mockito.any(BigInteger.class))).thenReturn(num);

        // Create real XWPFAbstractNum
        XWPFAbstractNum abstractNum = new XWPFAbstractNum(ctAbstractNum);
        Mockito.when(numbering.getAbstractNum(Mockito.any(BigInteger.class))).thenReturn(abstractNum);

        // Mock wrapper's getNextAbstractNumID
        Mockito.when(Mockito.mock(com.deepoove.poi.xwpf.XWPFNumberingWrapper.class)
            .getNextAbstractNumID()).thenReturn(BigInteger.valueOf(2));

        // Create instance of the class under test
        com.deepoove.poi.render.processor.NumberingContinue processor = 
            new com.deepoove.poi.render.processor.NumberingContinue();

        // Use reflection to set private fields
        java.lang.reflect.Field consistCacheField = 
            com.deepoove.poi.render.processor.NumberingContinue.class.getDeclaredField("consistCache");
        consistCacheField.setAccessible(true);
        consistCacheField.set(processor, new HashMap<BigInteger, BigInteger>());

        java.lang.reflect.Field continueNumIDField = 
            com.deepoove.poi.render.processor.NumberingContinue.class.getDeclaredField("continueNumID");
        continueNumIDField.setAccessible(true);
        continueNumIDField.set(processor, null);

        // Invoke the method - this should trigger ctAbstractNum.setAbstractNumId()
        processor.updateNumbering(sourceParagraph, targetParagraph);
    }
}

