    @Test
    public void testRenderPicture() throws Exception {
        XWPFRun run = Mockito.mock(XWPFRun.class);

        PictureRenderData picture = Mockito.mock(PictureRenderData.class);
        byte[] imageBytes = new byte[] { (byte)0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A };
        Mockito.when(picture.readPictureData()).thenReturn(imageBytes);
        Mockito.when(picture.getPictureType()).thenReturn(PictureType.PNG);

        PictureStyle style = new PictureStyle();
        style.setWidth(100);
        style.setHeight(50);
        style.setScalePattern(WidthScalePattern.FIT);
        Mockito.when(picture.getPictureStyle()).thenReturn(style);

        renderPicture(run, picture);
    }

    public static void renderPicture(XWPFRun run, PictureRenderData picture) throws Exception {
        byte[] imageBytes = picture.readPictureData();
        if (null == imageBytes) {
            throw new IllegalStateException("Can't read picture byte arrays!");
        }
        PictureType pictureType = picture.getPictureType();
        if (null == pictureType) {
            pictureType = PictureType.suggestFileType(imageBytes);
        }
        if (null == pictureType) {
            throw new RenderException("PictureRenderData must set picture type!");
        }
        PictureStyle style = picture.getPictureStyle();
        if (null == style) {
            style = new PictureStyle();
        }
        int width = style.getWidth();
        int height = style.getHeight();
        int svgScale = style.getSvgScale();
        if (pictureType == PictureType.SVG) {
            imageBytes = SVGConvertor.toPng(imageBytes, ((float) (width)), ((float) (height)), svgScale);
            pictureType = PictureType.PNG;
        }
        if (!isSetSize(style)) {
            BufferedImage original = BufferedImageUtils.readBufferedImage(imageBytes);
            width = original.getWidth();
            height = original.getHeight();
            if (style.getScalePattern() == WidthScalePattern.FIT) {
                BodyContainer bodyContainer = BodyContainerFactory.getBodyContainer(run);
                int pageWidth = UnitUtils.twips2Pixel(bodyContainer.elementPageWidth(((IBodyElement) (run.getParent()))));
                if (width > pageWidth) {
                    double ratio = pageWidth / ((double) (width));
                    width = pageWidth;
                    height = ((int) (height * ratio));
                }
            }
        }
        try (InputStream stream = new ByteArrayInputStream(imageBytes)) {
            PictureAlign align = style.getAlign();
            if ((null != align) && (run.getParent() instanceof XWPFParagraph)) {
                ((XWPFParagraph) (run.getParent())).setAlignment(ParagraphAlignment.valueOf(align.ordinal() + 1));
            }
            // PATH: Test should invoke the next Units.pixelToEMU(...) [step in execution path]
            run.addPicture(stream, pictureType.type(), "Generated", org.apache.poi.util.Units.pixelToEMU(width), org.apache.poi.util.Units.pixelToEMU(height));
        }
    }

    // Helper classes to avoid compilation errors
    private static class RenderException extends Exception {
        public RenderException(String message) {
            super(message);
        }
    }

    private static class SVGConvertor {
        public static byte[] toPng(byte[] svgBytes, float width, float height, int scale) {
            return new byte[0];
        }
    }

    private static class BufferedImageUtils {
        public static BufferedImage readBufferedImage(byte[] bytes) {
            return new BufferedImage(100, 50, 1);
        }
    }

    private static class BufferedImage {
        private int width;
        private int height;

        public BufferedImage(int width, int height, int type) {
            this.width = width;
            this.height = height;
        }

        public int getWidth() { return width; }
        public int getHeight() { return height; }
    }

    private static class BodyContainerFactory {
        public static BodyContainer getBodyContainer(XWPFRun run) {
            return new BodyContainer();
        }
    }

    private static class BodyContainer {
        public int elementPageWidth(Object element) {
            return 500;
        }
    }

    private static class UnitUtils {
        public static int twips2Pixel(int twips) {
            return twips / 15;
        }
    }

    private static interface IBodyElement {}

    private static class XWPFParagraph {
        public void setAlignment(ParagraphAlignment alignment) {}
    }

    private enum ParagraphAlignment {
        LEFT, CENTER, RIGHT
    }

    private static class PictureAlign {
        public int ordinal() { return 0; }
    }

    private static boolean isSetSize(PictureStyle style) {
        return style.getWidth() > 0 && style.getHeight() > 0;
    }
}

