import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTRPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTColor;

import static org.mockito.Mockito.when;

public class StyleUtilsstyleRun_CTColorisSetThemeColorFikaTest {

    @Test
    public void testStyleRunInvokesIsSetThemeColor() throws Exception {
        // Create mock XWPFRun
        XWPFRun run = Mockito.mock(XWPFRun.class);

        // Create mock CTRPr that will return a CTColor with theme color set
        CTRPr pr = Mockito.mock(CTRPr.class);
        CTColor ctColor = Mockito.mock(CTColor.class);

        // Setup mock behavior to reach the target method
        when(pr.sizeOfColorArray()).thenReturn(1);
        when(pr.getColorArray(0)).thenReturn(ctColor);
        when(ctColor.isSetThemeColor()).thenReturn(true);

        // Use reflection to set up the getRunProperties method
        java.lang.reflect.Method getRunPropertiesMethod = StyleUtils.class
                .getDeclaredMethod("getRunProperties", XWPFRun.class);
        getRunPropertiesMethod.setAccessible(true);
        when(run.getCTR()).thenReturn(null); // Ensure getCTR returns null to use reflection
        // We'll bypass the actual getRunProperties call by using a test wrapper

        // Create a style with color to trigger the color setting path
        Style style = Mockito.mock(Style.class);
        when(style.getColor()).thenReturn("#FF0000");
        when(style.getFontSize()).thenReturn(0.0);
        when(style.getFontFamily()).thenReturn(null);
        when(style.getWesternFontFamily()).thenReturn(null);
        when(style.getHighlightColor()).thenReturn(null);
        when(style.isBold()).thenReturn(null);
        when(style.isItalic()).thenReturn(null);
        when(style.isStrike()).thenReturn(null);
        when(style.getUnderlinePatterns()).thenReturn(null);
        when(style.getCharacterSpacing()).thenReturn(0);
        when(style.getVertAlign()).thenReturn(null);

        // Create a test instance that overrides getRunProperties
        StyleUtils instance = new StyleUtils() {};
        java.lang.reflect.Field field = StyleUtils.class.getDeclaredField("INSTANCE");
        field.setAccessible(true);

        // Temporarily replace the method behavior using a wrapper class
        StyleUtils original = (StyleUtils) field.get(null);
        try {
            // Create a proxy that intercepts getRunProperties
            StyleUtils proxy = (StyleUtils) java.lang.reflect.Proxy.newProxyInstance(
                StyleUtils.class.getClassLoader(),
                new Class[]{StyleUtils.class},
                (proxyObj, method, args) -> {
                    if (method.getName().equals("getRunProperties")) {
                        return pr;
                    }
                    return method.invoke(original, args);
                }
            );
            field.set(null, proxy);

            // Invoke the target method
            StyleUtils.styleRun(run, style);
        } finally {
            // Restore original instance
            field.set(null, original);
        }
    }
}

