    @Test
    public void testStylePprInvokesUnsetHanging() throws Exception {
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        CTP ctP = Mockito.mock(CTP.class);
        CTPPr ctPPr = Mockito.mock(CTPPr.class);
        CTInd ctInd = Mockito.mock(CTInd.class);
        CTPBdr ctPBdr = Mockito.mock(CTPBdr.class);
        CTShd ctShd = Mockito.mock(CTShd.class);

        Mockito.when(paragraph.getCTP()).thenReturn(ctP);
        Mockito.when(ctP.isSetPPr()).thenReturn(true);
        Mockito.when(ctP.getPPr()).thenReturn(ctPPr);
        Mockito.when(ctPPr.isSetInd()).thenReturn(true);
        Mockito.when(ctPPr.getInd()).thenReturn(ctInd);
        Mockito.when(ctPPr.isSetPBdr()).thenReturn(true);
        Mockito.when(ctPPr.getPBdr()).thenReturn(ctPBdr);
        Mockito.when(ctPPr.isSetShd()).thenReturn(true);
        Mockito.when(ctPPr.getShd()).thenReturn(ctShd);
        Mockito.when(ctPPr.isSetKeepLines()).thenReturn(true);
        Mockito.when(ctPPr.getKeepLines()).thenReturn(Mockito.mock(CTOnOff.class));
        Mockito.when(ctPPr.isSetWidowControl()).thenReturn(true);
        Mockito.when(ctPPr.getWidowControl()).thenReturn(Mockito.mock(CTOnOff.class));
        Mockito.when(ctPPr.isSetWordWrap()).thenReturn(true);
        Mockito.when(ctPPr.getWordWrap()).thenReturn(Mockito.mock(CTOnOff.class));

        Mockito.when(ctInd.isSetHanging()).thenReturn(true);

        ParagraphStyle style = ParagraphStyle.builder()
            .withIndentHangingChars(2.0)
            .withIndentLeftChars(1.0)
            .withIndentRightChars(1.0)
            .withIndentFirstLineChars(1.0)
            .withSpacing(1.0)
            .withSpacingBeforeLines(1.0)
            .withSpacingAfterLines(1.0)
            .withSpacingBefore(1.0)
            .withSpacingAfter(1.0)
            .withAlign(ParagraphAlignment.LEFT)
            .withLeftBorder(BorderStyle.builder().build())
            .withTopBorder(BorderStyle.builder().build())
            .withRightBorder(BorderStyle.builder().build())
            .withBottomBorder(BorderStyle.builder().build())
            .withBackgroundColor("FFFFFF")
            .withShadingPattern(XWPFShadingPattern.CLEAR)
            .withStyleId("Normal")
            .withKeepLines(true)
            .withKeepNext(true)
            .withPageBreakBefore(true)
            .withWidowControl(true)
            .withAllowWordBreak(true)
            .withNumId(1L)
            .withLvl(0)
            .build();

        StyleUtils.stylePpr(paragraph, style);
    }
}

