import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;

public class StyleUtilsstylePpr_CTPPraddNewKeepLinesFikaTest {

    @Test
    public void testStylePprInvokesAddNewKeepLines() throws Exception {
        // Create mock paragraph with CTP that has no PPr initially
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        CTP mockCtp = Mockito.mock(CTP.class);
        CTPPr mockPr = Mockito.mock(CTPPr.class);

        Mockito.when(paragraph.getCTP()).thenReturn(mockCtp);
        Mockito.when(mockCtp.isSetPPr()).thenReturn(false);
        Mockito.when(mockCtp.addNewPPr()).thenReturn(mockPr);

        // Mock the keepLines condition path
        Mockito.when(mockPr.isSetKeepLines()).thenReturn(false);
        CTOnOff mockKeepLines = Mockito.mock(CTOnOff.class);
        Mockito.when(mockPr.addNewKeepLines()).thenReturn(mockKeepLines);

        // Create style with keepLines set to trigger the target method
        ParagraphStyle style = new ParagraphStyle();
        style.setKeepLines(true);

        // Execute the method under test
        StyleUtils.stylePpr(paragraph, style);
    }
}

