package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;

import static org.mockito.Mockito.*;

public class StyleUtilsstylePpr_XWPFParagraphsetSpacingBeforeFikaTest {

    @Test
    public void testStylePprInvokesSetSpacingBefore() {
        XWPFParagraph mockParagraph = mock(XWPFParagraph.class);
        ParagraphStyle mockStyle = mock(ParagraphStyle.class);

        when(mockStyle.getSpacingBefore()).thenReturn(12.0);

        StyleUtils.stylePpr(mockParagraph, mockStyle);
    }

    // Supporting classes needed for compilation
    static class ParagraphStyle {
        private Object align;
        private Object spacing;
