        private Double indentHangingChars;
        private Double indentFirstLineChars;
        private Object leftBorder;
        private Object topBorder;
        private Object rightBorder;
        private Object bottomBorder;
        private Object backgroundColor;
        private Object shadingPattern;
        private String styleId;
        private Boolean keepLines;
        private Boolean keepNext;
        private Boolean pageBreakBefore;
        private Boolean widowControl;
        private Boolean allowWordBreak;
        private Long numId;
        private Long lvl;

        public Object getAlign() { return align; }
        public Object getSpacing() { return spacing; }
        public Object getSpacingRule() { return spacingRule; }
        public Double getSpacingBeforeLines() { return spacingBeforeLines; }
        public Double getSpacingAfterLines() { return spacingAfterLines; }
        public Double getSpacingBefore() { return spacingBefore; }
        public Double getSpacingAfter() { return spacingAfter; }
        public Double getIndentLeftChars() { return indentLeftChars; }
        public Double getIndentRightChars() { return indentRightChars; }
        public Double getIndentHangingChars() { return indentHangingChars; }
        public Double getIndentFirstLineChars() { return indentFirstLineChars; }
        public Object getLeftBorder() { return leftBorder; }
        public Object getTopBorder() { return topBorder; }
        public Object getRightBorder() { return rightBorder; }
        public Object getBottomBorder() { return bottomBorder; }
        public Object getBackgroundColor() { return backgroundColor; }
        public Object getShadingPattern() { return shadingPattern; }
        public String getStyleId() { return styleId; }
        public Boolean getKeepLines() { return keepLines; }
        public Boolean getKeepNext() { return keepNext; }
        public Boolean getPageBreakBefore() { return pageBreakBefore; }
        public Boolean getWidowControl() { return widowControl; }
        public Boolean getAllowWordBreak() { return allowWordBreak; }
        public Long getNumId() { return numId; }
        public Long getLvl() { return lvl; }
    }

    static class StyleUtils {
        public static void stylePpr(XWPFParagraph paragraph, ParagraphStyle style) {
            if ((null == paragraph) || (null == style)) {
                return;
            }
            if (null != style.getAlign()) {
                paragraph.setAlignment(style.getAlign());
            }
            if (null != style.getSpacing()) {
                paragraph.setSpacingBetween(style.getSpacing(), null == style.getSpacingRule() ? LineSpacingRule.AUTO : style.getSpacingRule());
            }
            if (null != style.getSpacingBeforeLines()) {
                paragraph.setSpacingBeforeLines(new BigInteger(String.valueOf(Math.round(style.getSpacingBeforeLines() * 100.0))).intValue());
            }
            if (null != style.getSpacingAfterLines()) {
                paragraph.setSpacingAfterLines(new BigInteger(String.valueOf(Math.round(style.getSpacingAfterLines() * 100.0))).intValue());
            }
            if (null != style.getSpacingBefore()) {
                paragraph.setSpacingBefore(UnitUtils.point2Twips(style.getSpacingBefore()));
            }
            if (null != style.getSpacingAfter()) {
                paragraph.setSpacingAfter(UnitUtils.point2Twips(style.getSpacingAfter()));
            }
        }
    }

    static class LineSpacingRule {
        public static final Object AUTO = new Object();
    }

    static class UnitUtils {
        public static int point2Twips(double points) {
            return (int) (points * 20);
        }
    }
}

