import java.math.BigInteger;

public class StyleUtilsstylePpr_CTPBdraddNewRightFikaTest {

    @Test
    public void testStylePprInvokesAddNewRight() throws Exception {
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        ParagraphStyle style = Mockito.mock(ParagraphStyle.class);
        BorderStyle rightBorder = Mockito.mock(BorderStyle.class);

        CTP mockCtp = Mockito.mock(CTP.class);
        CTPPr mockPr = Mockito.mock(CTPPr.class);
        CTPBdr mockPBdr = Mockito.mock(CTPBdr.class);

        Mockito.when(paragraph.getCTP()).thenReturn(mockCtp);
        Mockito.when(mockCtp.isSetPPr()).thenReturn(true);
        Mockito.when(mockCtp.getPPr()).thenReturn(mockPr);
        Mockito.when(mockPr.isSetPBdr()).thenReturn(false);
        Mockito.when(mockPr.addNewPBdr()).thenReturn(mockPBdr);
        Mockito.when(mockPBdr.isSetRight()).thenReturn(false);

        Mockito.when(style.getRightBorder()).thenReturn(rightBorder);

        StyleUtils.stylePpr(paragraph, style);
    }
}

