import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.ParagraphAlignment;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTP;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTPPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTInd;
import com.deepoove.poi.data.style.ParagraphStyle;
import com.deepoove.poi.data.style.BorderStyle;
import com.deepoove.poi.data.style.LineSpacingRule;
import com.deepoove.poi.data.style.XWPFShadingPattern;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;

public class StyleUtilsstylePpr_CTIndsetRightCharsFikaTest {

    @Test
    public void testStylePprInvokesSetRightChars() {
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        CTP mockCtp = Mockito.mock(CTP.class);
        CTPPr mockPPr = Mockito.mock(CTPPr.class);
        CTInd mockInd = Mockito.mock(CTInd.class);

        Mockito.when(paragraph.getCTP()).thenReturn(mockCtp);
        Mockito.when(mockCtp.isSetPPr()).thenReturn(true);
        Mockito.when(mockCtp.getPPr()).thenReturn(mockPPr);
        Mockito.when(mockPPr.isSetInd()).thenReturn(true);
        Mockito.when(mockPPr.getInd()).thenReturn(mockInd);
        Mockito.when(mockInd.isSetRight()).thenReturn(false);

        ParagraphStyle style = new ParagraphStyle();
        style.setIndentRightChars(2.5);
        style.setIndentLeftChars(1.5);
        style.setAlign(ParagraphAlignment.LEFT);
        style.setSpacing(1.5);
        style.setSpacingRule(LineSpacingRule.EXACT);
        style.setSpacingBeforeLines(1.0);
        style.setSpacingAfterLines(1.0);
        style.setSpacingBefore(10.0);
        style.setSpacingAfter(10.0);
        style.setIndentHangingChars(0.5);
        style.setIndentFirstLineChars(0.5);
        style.setLeftBorder(new BorderStyle());
        style.setTopBorder(new BorderStyle());
        style.setRightBorder(new BorderStyle());
        style.setBottomBorder(new BorderStyle());
        style.setBackgroundColor("FFFFFF");
        style.setShadingPattern(XWPFShadingPattern.CLEAR);
        style.setStyleId("Normal");
        style.setKeepLines(true);
        style.setKeepNext(true);
        style.setPageBreakBefore(true);
        style.setWidowControl(true);
        style.setAllowWordBreak(true);
        style.setNumId(1L);
        style.setLvl(0L);

        StyleUtils.stylePpr(paragraph, style);
    }
}

