public XDDFOfPieChartData(XDDFChart parent, CTOfPieChart chart) {
    super(parent);
    this.chart = chart;
    this.seriesNum = parent.getChartSeries().size();
    for (CTPieSer series : chart.getSerList()) {
        this.series.add(new Series(series, series.getCat(), series.getVal()));
    }
}

