@Override
public void doRender(ChartTemplate eleTemplate, ChartSingleSeriesRenderData data, XWPFTemplate template) throws Exception {
    XWPFChart chart = eleTemplate.getChart();
    XDDFChartData pie = ChartUtils.getChartSeries(chart).get(0);
    SeriesRenderData seriesDatas = data.getSeriesData();
    XDDFDataSource<?> categoriesData = null;
    if (pie instanceof XDDFScatterChartData) {
        // PATH: Test should invoke the next AbstractChartTemplateRenderPolicy.createNumbericalDataSource(...) [step in execution path]
        categoriesData = createNumbericalDataSource(chart, toNumberArray(data.getCategories()), 0);
    } else {
        categoriesData = createStringDataSource(chart, data.getCategories(), 0);
    }
    XDDFNumericalDataSource<? extends Number> valuesData = createNumbericalDataSource(chart, seriesDatas.getValues(), 1);
    XDDFChartData.Series currentSeries = pie.getSeries(0);
    currentSeries.replaceData(categoriesData, valuesData);
    currentSeries.setTitle(seriesDatas.getName(), chart.setSheetTitle(seriesDatas.getName(), 1));
    updateCTTable(chart.getWorkbook().getSheetAt(0), Arrays.asList(seriesDatas));
    plot(chart, pie);
    setTitle(chart, data.getChartTitle());
    setAxisTitle(chart, data.getxAxisTitle(), data.getyAxisTitle());
}

protected <N extends Number> XDDFNumericalDataSource<Number> createNumbericalDataSource(XWPFChart chart, N[] data, int col) {
    return XDDFDataSourcesFactory.fromArray(data, chart.formatRange(new CellRangeAddress(FIRST_ROW, data.length, col, col)), col);
}

