    @Test
    public void testNiceDocumentRead() throws IOException {
        byte[] docBytes = createMinimalDocx();
        XWPFDocument document = new XWPFDocument(new ByteArrayInputStream(docBytes));

        NiceXWPFDocumentWrapper wrapper = new NiceXWPFDocumentWrapper(document);
        wrapper.niceDocumentRead();
    }

    private static byte[] createMinimalDocx() {
        XWPFDocument doc = new XWPFDocument();
        doc.createParagraph().createRun().setText("Test");

        // Create at least one header and footer to trigger loops
        XWPFHeader header = doc.createHeader(org.apache.poi.xwpf.usermodel.HeaderFooterType.DEFAULT);
        header.createParagraph().createRun().setText("Header");

        XWPFFooter footer = doc.createFooter(org.apache.poi.xwpf.usermodel.HeaderFooterType.DEFAULT);
        footer.createParagraph().createRun().setText("Footer");

        try (java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream()) {
            doc.write(baos);
            return baos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static class NiceXWPFDocumentWrapper {
        private final XWPFDocument document;
        private final List<Object> contentControls = new ArrayList<>();
        private final List<Object> bodyElements = new ArrayList<>();
        private final List<Object> structuredDocumentTags = new ArrayList<>();

        public NiceXWPFDocumentWrapper(XWPFDocument document) {
            this.document = document;
            // Add at least one content control to enter the if block
            this.contentControls.add(new Object());
        }

        public XWPFDocument getDocument() {
            return document;
        }

        public List<Object> getHeaderList() {
            return new ArrayList<>(document.getHeaderList());
        }

        public List<Object> getFooterList() {
            return new ArrayList<>(document.getFooterList());
        }

        private void read(Object obj) {
            // Empty implementation as required
        }

        private void niceDocumentRead() throws IOException {
            read(this);
            this.getHeaderList().forEach(header -> read(header));
            this.getFooterList().forEach(header -> read(header));

            if (!contentControls.isEmpty()) {
                XmlCursor docCursor = getDocument().newCursor();
                docCursor.selectPath("./*");
                while (docCursor.toNextSelection()) {
                    XmlObject o = docCursor.getObject();
                    if (o instanceof CTBody) {
                        XmlCursor bodyCursor = o.newCursor();
                        bodyCursor.selectPath("./*");
                        while (bodyCursor.toNextSelection()) {
                            XmlObject bodyObj = bodyCursor.getObject();
                            if (bodyObj instanceof CTSdtBlock) {
                                // This will create the structured document tag objects
                                // but we don't need to actually instantiate XWPFStructuredDocumentTag
                                bodyElements.add(bodyObj);
                                structuredDocumentTags.add(bodyObj);
                            }
                        }
                        bodyCursor.dispose();
                    }
                }
                docCursor.dispose();
            }
        }
    }
}

