                }
                CTTitle ctTitle = chart.getCTChart().getTitle();
                // We need to handle setCTTitle call - create a simple implementation
                // that returns false to avoid NPE
                boolean isSet = false; // setCTTitle would normally be called here
                if (!isSet) {
                    chart.setTitleText(title);
                    chart.setTitleOverlay(false);
                }
            }
        };

        // Use reflection to invoke the method
