public void resolveParagraph(XWPFParagraph paragraph, List<MetaTemplate> metaTemplates, Deque<BlockTemplate> stack) // PATH: Test should invoke the next TemplateResolver.resolveXWPFRuns(...) [step in execution path]
{
    XWPFParagraphWrapper paragraphWrapper = new XWPFParagraphWrapper(paragraph);
    new RunningRunBody(new ParagraphContext(paragraphWrapper), templatePattern).refactorRun();
    resolveXWPFRuns(paragraph.getRuns(), metaTemplates, stack);
    paragraphWrapper.getSDTs().forEach(sdtEle -> addNewMeta(metaTemplates, stack, resolveSDTElements(sdtEle.getContent())));
}

private void resolveXWPFRuns(List<XWPFRun> runs, final List<MetaTemplate> metaTemplates, final Deque<BlockTemplate> stack) {
    for (XWPFRun run : runs) {
        String text = null;
        if (StringUtils.isBlank(text = run.getText(0))) {
            // textbox
            List<MetaTemplate> visitBodyElements = resolveTextbox(run);
            if (!visitBodyElements.isEmpty()) {
                addNewMeta(metaTemplates, stack, visitBodyElements);
                continue;
            }
            // picture
            List<PictureTemplate> pictureTemplates = resolveXWPFPictures(run.getEmbeddedPictures());
            if (!pictureTemplates.isEmpty()) {
                addNewMeta(metaTemplates, stack, pictureTemplates);
                continue;
            }
            // w:pict v:imagedata
            PictImageTemplate pictImageTemplate = resolvePictImage(run);
            if (null != pictImageTemplate) {
                addNewMeta(metaTemplates, stack, pictImageTemplate);
                continue;
            }
            // chart
            // PATH: Test should invoke the next TemplateResolver.resolveXWPFChart(...) [step in execution path]
            ChartTemplate chartTemplate = resolveXWPFChart(run);
            if (null != chartTemplate) {
                addNewMeta(metaTemplates, stack, chartTemplate);
                continue;
            }
            continue;
        }
        RunTemplate runTemplate = ((RunTemplate) (parseTemplateFactory(text, run, run)));
        if (null == runTemplate) {
            continue;
        }
        char charValue = runTemplate.getSign().charValue();
        if (charValue == config.getIterable().getLeft()) {
            IterableTemplate freshIterableTemplate = new IterableTemplate(runTemplate);
            stack.push(freshIterableTemplate);
        } else if (charValue == config.getIterable().getRight()) {
            if (stack.isEmpty()) {
                throw new ResolverException("Mismatched start/end tags: No start mark found for end mark " + runTemplate);
            }
            BlockTemplate latestIterableTemplate = stack.pop();
            if (StringUtils.isNotEmpty(runTemplate.getTagName()) && (!latestIterableTemplate.getStartMark().getTagName().equals(runTemplate.getTagName()))) {
                throw new ResolverException((("Mismatched start/end tags: start mark " + latestIterableTemplate.getStartMark()) + " does not match to end mark ") + runTemplate);
            }
