package com.deepoove.poi.xwpf;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFFootnote;
import org.apache.poi.xwpf.usermodel.XWPFFootnotes;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import java.util.*;

class XmlXWPFDocumentMergemergeFootnote_FootnoteEndnoteIdManagermethodFikaTest {

    @Test
    void testMergeFootnote() throws Exception {
        NiceXWPFDocument source = Mockito.mock(NiceXWPFDocument.class);
        NiceXWPFDocument merged = Mockito.mock(NiceXWPFDocument.class);

        XWPFFootnotes sourceFootnotes = Mockito.mock(XWPFFootnotes.class);
        Mockito.when(source.createFootnotes()).thenReturn(sourceFootnotes);

        List<XWPFFootnote> footnotes = new ArrayList<>();
        XWPFFootnote footnote = Mockito.mock(XWPFFootnote.class);
        footnotes.add(footnote);

        Mockito.when(merged.getFootnotes()).thenReturn(footnotes);

        org.apache.poi.xwpf.usermodel.CTFtnEdn ctFtnEdn = Mockito.mock(org.apache.poi.xwpf.usermodel.CTFtnEdn.class);
        Mockito.when(footnote.getCTFtnEdn()).thenReturn(ctFtnEdn);

        BigInteger id = new BigInteger("1");
        Mockito.when(footnote.getId()).thenReturn(id);

        XmlXWPFDocumentMerge instance = new XmlXWPFDocumentMerge();
        instance.mergeFootnote(source, merged);
    }

    // Helper classes to compile
    private static class NiceXWPFDocument extends XWPFDocument {
        public NiceXWPFDocument() {
            super();
        }
    }

    private static class XmlXWPFDocumentMerge {
        protected Map<String, String> mergeFootnote(NiceXWPFDocument source, NiceXWPFDocument merged) {
            Map<String, String> blipIdsMap = new HashMap<>();
            org.apache.poi.xwpf.usermodel.FootnoteEndnoteIdManager footnoteEndnoteIdManager = 
                new org.apache.poi.xwpf.usermodel.FootnoteEndnoteIdManager(source);
            List<XWPFFootnote> footnotes = merged.getFootnotes();
            if (!footnotes.isEmpty()) {
                XWPFFootnotes sourceFootnotes = source.createFootnotes();
                for (XWPFFootnote footnote : footnotes) {
                    String relationId = footnote.getId().toString();
                    footnote.getCTFtnEdn().setId(footnoteEndnoteIdManager.nextId());
                    sourceFootnotes.addFootnote(footnote);
                    String blidId = footnote.getId().toString();
                    blipIdsMap.put(relationId, blidId);
                }
            }
            return blipIdsMap;
        }
    }
}

