                throws InvalidFormatException {
            Map<String, String> blipIdsMap = new HashMap<String, String>();
            PackageRelationshipCollection imagePart = merged.getPackagePart().getRelationshipsByType(PackageRelationshipTypes.IMAGE_PART);
            Iterator<PackageRelationship> iterator = imagePart.iterator();
            while (iterator.hasNext()) {
                PackageRelationship relationship = iterator.next();
                if (relationship.getTargetMode() == TargetMode.EXTERNAL) {
                    PackageRelationship relationshipNew = source.getPackagePart().addExternalRelationship(
                            relationship.getTargetURI().toString(), 
                            XWPFRelation.IMAGES.getRelation());
                    blipIdsMap.putIfAbsent(relationship.getId(), relationshipNew.getId());
                }
            } 
            return blipIdsMap;
        }

        public PackagePart getPackagePart() {
            return null;
        }
    }

    // Minimal implementation of PackageRelationshipTypes
    private static class PackageRelationshipTypes {
        public static final String IMAGE_PART = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/image";
    }
}

