    return addPart.replaceAll(CROSS_REPLACE_STRING, "");
}

protected Map<String, String> mergeExternalPicture(NiceXWPFDocument source, NiceXWPFDocument merged) throws InvalidFormatException {
    Map<String, String> blipIdsMap = new HashMap<String, String>();
    PackageRelationshipCollection imagePart = merged.getPackagePart().getRelationshipsByType(PackageRelationshipTypes.IMAGE_PART);
    Iterator<PackageRelationship> iterator = imagePart.iterator();
    while (iterator.hasNext()) {
        PackageRelationship relationship = iterator.next();
        if (relationship.getTargetMode() == TargetMode.EXTERNAL) {
            PackageRelationship relationshipNew = source.getPackagePart().addExternalRelationship(relationship.getTargetURI().toString(), XWPFRelation.IMAGES.getRelation());
            // PATH: Test should invoke the next PackageRelationship.getId(...) [step in execution path]
            blipIdsMap.putIfAbsent(relationship.getId(), relationshipNew.getId());
        }
    } 
    return blipIdsMap;
}

