        addPart = addPart.replaceAll(("r:id=\"" + relaId) + "\"", ("r:id=\"" + attachmentIdsMap.get(relaId)) + "\"");
    }
    // footnote id
    for (String relaId : footnoteIdsMap.keySet()) {
        footnoteIdsMap.put(relaId, footnoteIdsMap.get(relaId) + CROSS_REPLACE_STRING);
